import { Injectable } from '@angular/core';
import { Supplier } from '../pages/supplier/supplier';
import { HttpClient } from '@angular/common/http';
import { Observable } from 'rxjs';
import { environment } from '../environments/environments';
@Injectable({
  providedIn: 'root'
})
export class SupplierService {
   private ApiUrl = `${environment.apiUrl}/supplier/`;

  constructor(private http: HttpClient) {}

  getSuppliers(): Observable<Supplier[]>{
    return this.http.get<Supplier[]>(`${this.ApiUrl}`);
  }

  CreateSupplier(data: Supplier ): Observable<Supplier> {
  return this.http.post<Supplier>(`${this.ApiUrl}create`, data);
}
  getSupplierById(id: number): Observable<Supplier> {
  return this.http.get<Supplier>(`${this.ApiUrl}${id}`);
}

  editSupplier(id: number, party: Supplier): Observable<Supplier> {
  return this.http.put<Supplier>(`${this.ApiUrl}edit-supplier/${id}`, party);
}
}
